  let operator = '';
  let rest = content;

  if (OPERATORS.includes(firstChar)) {
    operator = firstChar;
    rest = content.slice(1);
  } else if (RESERVED_OPERATORS.includes(firstChar)) {
    throw new UriTemplateError(`reserved operator '${firstChar}' at ${bracePos}`, bracePos);
  }

  if (rest === '') {
    throw new UriTemplateError(`empty variable specification at ${bracePos}`, bracePos);
  }

  const specs = rest.split(',');
  const variables = [];
  for (const spec of specs) {
    if (spec === '') {
      throw new UriTemplateError(`empty variable specification at ${bracePos}`, bracePos);
    }
    variables.push(parseVarSpec(spec, bracePos));
  }

  return { type: 'expression', operator, variables };
