export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const parts = [];
  let literalBuf = '';
  let i = 0;
  const len = template.length;

  while (i < len) {
    const ch = template[i];
    if (ch === '{') {
      if (literalBuf !== '') {
        parts.push({ type: 'literal', value: literalBuf });
